function resolveNibProps(props: HeroTickerNibProps) {
  return {
    visible: props.visible ?? true,
    active: props.active ?? true,
    phrase: props.phrase ?? '',
    testId: props.dataTestId ?? props['data-testid'] ?? 'hero-ticker-nib',
  };
}

function createQuillSvg() {
  return createElement(
    'svg',
    {
      viewBox: '0 0 67.733333 67.733333',
      width: 52,
      height: 52,
      className: 'hero-ticker_quill-img',
      fill: 'currentColor',
      'aria-hidden': 'true',
    },
    createElement(
      'g',
      { transform: 'matrix(2.8615328,0,0,2.8615328,492.2471,-1090.092)' },
      createElement('path', { d: QUILL_PATH_D, fill: 'currentColor' })
    )
  );
}

export const HeroTickerNib: FC<HeroTickerNibProps> = (props) => {
  const { visible, active, phrase, testId } = resolveNibProps(props);
  const trajectory = calculateQuillTrajectory(phrase, props.progress, active);
  const nibRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    applyNibStyle(nibRef.current, trajectory, props.accentVar);
  }, [trajectory, props.accentVar]);

  if (!visible) return null;

  return (
    <Box
      ref={nibRef}
      data-testid={testId}
      data-active={active ? 'true' : 'false'}
      className="hero-ticker_nib"
      aria-hidden="true"
    >
      {createQuillSvg()}

      {active && (
        <Box
          className="hero-ticker_ink-droplet"
          data-downstroke={trajectory.isDownstroke ? 'true' : 'false'}
          aria-hidden="true"
        />
      )}
    </Box>
  );
};
